                            Year = Value(PCF.CurrentYear)
                        )
                    )
                },
                Patch(
                    'Capex Project Costs',
                    If(
                        IsBlank(varCapexProjectCostRecord),
                        Defaults('Capex Project Costs'),
                        varCapexProjectCostRecord
                    ),
                    If(
                        IsBlank(varCapexProjectCostRecord),
                        {
                            Name: gblSelectedProject.'Project Name' & "-" & PCF.SubAccountID.Name & "-" & Value(PCF.CurrentYear),
